static BOOL test_GetPrintProcessorDirectory(struct torture_context *tctx, LPSTR servername, LPSTR architecture) { DWORD levels[]= { 1 }; DWORD success[] = { 1 }; DWORD i; LPBYTE buffer = NULL; for (i=0; i < ARRAY_SIZE(levels); i++) { DWORD needed = 0; DWORD err = 0; char tmp[1024]; torture_comment(tctx, "Testing GetPrintProcessorDirectory(%s) level %d", architecture, levels[i]); GetPrintProcessorDirectory(servername, architecture, levels[i], NULL, 0, &needed); err = GetLastError(); if (err == ERROR_INSUFFICIENT_BUFFER) { err = 0; buffer = malloc(needed); torture_assert(tctx, buffer, "malloc failed"); if (!GetPrintProcessorDirectory(servername, architecture, levels[i], buffer, needed, &needed)) { err = GetLastError(); } } if (err) { sprintf(tmp, "GetPrintProcessorDirectory failed level %d on [%s] (buffer size = %d), error: %s
", levels[i], servername, needed, errstr(err)); if (success[i]) { torture_fail(tctx, tmp); } else { torture_warning(tctx, tmp); } } if (tctx->print) { printf("	Print Processor Directory	= %s

", (LPSTR)buffer); } free(buffer); buffer = NULL; } return TRUE; }

